import hashlib,json
from pathlib import Path
base=Path('products/distribution/catalogue-referral')
names=['item-4-operator-decision-pointer.json','item-4-release-binding.json','operator-handoff.md']
records={}
for name in names:
 p=base/name
 if p.is_file():
  raw=p.read_bytes()
  records[name]={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
 else:
  records[name]={'available_in_selected_inputs':False}
out=Path('products/distribution/catalogue-referral/director-item-4-handoff-readback.json')
out.write_text(json.dumps({'records':records,'scope':'Artifact inventory for the existing item 4 decision. Presence and hashes alone do not establish authorization, submission or a buyer outcome.'},indent=2)+'\n')
print(out.read_text())
